        )
        .expect("config should parse");

        assert_eq!(config.device_id, "hid-1234");
        assert!(!config.device_id_explicit);
    }

    #[test]
    fn defaults_log_dir_to_app_support_logs() {
        let config = Config::default();
        assert!(config.log_dir.contains("ai-agent-update"));
        assert!(config.log_dir.ends_with("logs"));
    }
