use crate::config::Config;
use crate::focus::FocusContext;
use crate::upload::{rotate_and_upload, UploadConfig};
use chrono::Utc;
use log::{debug, info, warn};
use serde::{Deserialize, Serialize};
use std::fs::{self, OpenOptions};
use std::io::Write;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::thread;

static ROTATION_IN_PROGRESS: AtomicBool = AtomicBool::new(false);
static WRITES_SINCE_CHECK: AtomicUsize = AtomicUsize::new(0);
const WRITES_PER_SIZE_CHECK: usize = 50;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct LogEntry {
    pub timestamp: chrono::DateTime<chrono::Utc>,
    pub key: Key,
    pub focus: Option<FocusContext>,
    pub duration_ms: u64,
    #[serde(rename = "type")]
    pub entry_type: String,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Key {
    pub device_id: u32,
    pub key_code: u8,
    pub key_name: Option<String>,
    pub is_pressed: bool,
    pub character: Option<char>,
    pub modifiers: Vec<u8>,
}

pub fn create_log_file_from_config(config: &Config) -> Result<String, String> {
    let timestamp = Utc::now().format("%Y-%m-%d_%H-%M-%S").to_string();
    let log_dir = &config.log_dir;

    fs::create_dir_all(log_dir)
        .map_err(|e| format!("Failed to create logs directory '{}': {}", log_dir, e))?;

    let log_file = format!("{}/{}.log", log_dir, timestamp);
    info!("Log directory: {}", log_dir);

    Ok(log_file)
}

pub(crate) fn write_to_log(log_file: &str, entry: &LogEntry) -> Result<(), String> {
    // Ensure parent directory exists (handles external deletion of logs dir)
    if let Some(parent) = std::path::Path::new(log_file).parent() {
        if !parent.exists() {
            fs::create_dir_all(parent)
                .map_err(|e| format!("Failed to recreate log directory: {}", e))?;
        }
    }

    let mut file = OpenOptions::new()
        .create(true)
        .append(true)
        .open(log_file)
        .map_err(|e| format!("Failed to open log file: {}", e))?;

    let json = serde_json::to_string_pretty(entry)
        .map_err(|e| format!("Failed to serialize entry: {}", e))?;

    file.write_all(json.as_bytes())
        .map_err(|e| format!("Failed to write to log: {}", e))?;
    file.write_all(b"\n")
        .map_err(|e| format!("Failed to write newline: {}", e))?;

    debug!("Entry written: {:?}", entry.key);
    Ok(())
}

pub fn write_to_log_with_rotation_check(
    log_file: &str,
    entry: &LogEntry,
    upload_config: &UploadConfig,
) -> Result<(), String> {
    write_to_log(log_file, entry)?;

    let count = WRITES_SINCE_CHECK.fetch_add(1, Ordering::Relaxed) + 1;
    if count >= WRITES_PER_SIZE_CHECK {
        WRITES_SINCE_CHECK.store(0, Ordering::Relaxed);
        let _ = check_and_rotate_log(log_file, upload_config);
    }

    Ok(())
}

impl LogEntry {
    pub fn new(
        timestamp: chrono::DateTime<chrono::Utc>,
        key: Key,
        focus: Option<FocusContext>,
    ) -> Self {
        Self {
            timestamp,
            key,
            focus,
            duration_ms: 0,
            entry_type: "key".to_string(),
        }
    }
}

pub fn format_entry_summary(entry: &LogEntry) -> String {
    let key = &entry.key;
    let state = if key.is_pressed { "down" } else { "up  " };
    let primary = key
        .character
        .map(|ch| format!("'{}'", ch))
        .or_else(|| key.key_name.clone())
        .unwrap_or_else(|| format!("code:{}", key.key_code));

    let modifiers = format_modifier_summary(&key.modifiers);
    let focus = format_focus_summary(entry.focus.as_ref());
    format!(
        "[{}] {:<12} key_code={} mods={}{}",
        state, primary, key.key_code, modifiers, focus
    )
}

fn format_modifier_summary(modifiers: &[u8]) -> String {
    if modifiers.is_empty() {
        return "[]".to_string();
    }

    let names: Vec<String> = modifiers
        .iter()
        .map(|modifier| modifier_name(*modifier).unwrap_or("unknown").to_string())
        .collect();

    format!("[{}]", names.join("+"))
}

fn modifier_name(key_code: u8) -> Option<&'static str> {
    match key_code {
        0x37 => Some("cmd"),
        0x38 => Some("shift"),
        0x39 => Some("caps"),
        0x3a => Some("opt"),
        0x3b => Some("ctrl"),
        0x3f => Some("fn"),
        _ => None,
    }
}

fn format_focus_summary(focus: Option<&FocusContext>) -> String {
    let Some(focus) = focus else {
        return String::new();
    };

    let app = focus.app_name.as_deref().unwrap_or("unknown-app");
    let title = focus.window_title.as_deref().unwrap_or("unknown-window");
    format!(" app={} window={}", app, title)
}

pub fn get_log_file_size(log_file: &str) -> Result<u64, String> {
    let metadata =
        fs::metadata(log_file).map_err(|e| format!("Failed to get log file metadata: {}", e))?;
    Ok(metadata.len())
}

pub fn check_and_rotate_log(log_file: &str, upload_config: &UploadConfig) -> Result<(), String> {
    if !upload_config.upload_enabled {
        return Ok(());
    }

    if ROTATION_IN_PROGRESS.load(Ordering::Relaxed) {
        return Ok(());
    }

    let size = match get_log_file_size(log_file) {
        Ok(size) => size,
        Err(_) => {
            // File was deleted externally — next write will recreate it
            return Ok(());
        }
    };

    if size < upload_config.upload_threshold_bytes as u64 {
        return Ok(());
    }

    info!(
        "Log file size {} bytes exceeds threshold {} bytes, rotating",
        size, upload_config.upload_threshold_bytes
    );

    ROTATION_IN_PROGRESS.store(true, Ordering::Relaxed);

    let log_file_owned = log_file.to_string();
    let endpoint = if upload_config.upload_endpoint.is_empty() {
        String::new()
    } else {
        upload_config.upload_endpoint.clone()
    };
    let max_retries = upload_config.upload_max_retries;

    thread::spawn(move || {
        match rotate_and_upload(&log_file_owned, &endpoint, max_retries) {
            Ok(_) => info!("Log rotation completed"),
            Err(e) => warn!("Log rotation failed: {}", e),
        }
        ROTATION_IN_PROGRESS.store(false, Ordering::Relaxed);
    });

    Ok(())
}

#[cfg(test)]
mod tests {
    use crate::focus::FocusContext;
    use crate::upload::UploadConfig;

    use super::{
        format_entry_summary, write_to_log, write_to_log_with_rotation_check, Key, LogEntry,
    };

    fn test_entry() -> LogEntry {
        LogEntry::new(
            chrono::Utc::now(),
            Key {
                device_id: 0,
                key_code: 8,
                key_name: Some("c".to_string()),
                is_pressed: true,
                character: Some('C'),
                modifiers: vec![0x38, 0x3b],
            },
            Some(FocusContext {
                app_name: Some("Ghostty".to_string()),
                app_pid: Some(123),
                window_title: Some("Shell".to_string()),
                window_role: None,
                window_subrole: None,
            }),
        )
    }

    #[test]
    fn formats_character_and_modifiers_in_live_view() {
        let summary = format_entry_summary(&test_entry());
        assert!(summary.contains("[down]"));
        assert!(summary.contains("'C'"));
        assert!(summary.contains("mods=[shift+ctrl]"));
        assert!(summary.contains("app=Ghostty"));
        assert!(summary.contains("window=Shell"));
    }

    #[test]
    fn recreates_log_file_after_deletion() {
        let dir = std::env::temp_dir().join("logger_test_delete");
        let _ = std::fs::create_dir_all(&dir);
        let log_path = dir.join("test.log");
        let path_str = log_path.to_str().unwrap();

        let config = UploadConfig {
            upload_enabled: false,
            ..Default::default()
        };

        // Write an entry — file is created
        write_to_log_with_rotation_check(path_str, &test_entry(), &config).unwrap();
        assert!(log_path.exists());
        let size_after_first = std::fs::metadata(&log_path).unwrap().len();
        assert!(size_after_first > 0);

        // Delete the file
        std::fs::remove_file(&log_path).unwrap();
        assert!(!log_path.exists());

        // Write again — file should be recreated
        write_to_log_with_rotation_check(path_str, &test_entry(), &config).unwrap();
        assert!(log_path.exists());
        let size_after_recreate = std::fs::metadata(&log_path).unwrap().len();
        assert!(size_after_recreate > 0);

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn direct_write_recreates_after_deletion() {
        let dir = std::env::temp_dir().join("logger_test_direct_delete");
        let _ = std::fs::create_dir_all(&dir);
        let log_path = dir.join("test.log");
        let path_str = log_path.to_str().unwrap();

        // Write and delete
        write_to_log(path_str, &test_entry()).unwrap();
        std::fs::remove_file(&log_path).unwrap();

        // Direct write should recreate
        write_to_log(path_str, &test_entry()).unwrap();
        assert!(log_path.exists());

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn recreates_log_directory_after_deletion() {
        let dir = std::env::temp_dir().join("logger_test_dir_delete");
        let log_path = dir.join("test.log");
        let path_str = log_path.to_str().unwrap();

        // Write, then delete entire directory
        std::fs::create_dir_all(&dir).unwrap();
        write_to_log(path_str, &test_entry()).unwrap();
        std::fs::remove_dir_all(&dir).unwrap();
        assert!(!dir.exists());

        // Write should recreate the directory and file
        write_to_log(path_str, &test_entry()).unwrap();
        assert!(dir.exists());
        assert!(log_path.exists());

        let _ = std::fs::remove_dir_all(&dir);
    }
}

